# Find the best restaurant without using lambda by iterating
if len(parsed_restaurants) == 0:
    raise ValueError("No suitable Chinese restaurants found open on Monday under 34 euros.")

best_restaurant = parsed_restaurants[0]
for r in parsed_restaurants:
    if r.rating > best_restaurant.rating:
        best_restaurant = r

# Find the best car rental company without using lambda
if len(parsed_cars) == 0:
